  'steered':{w:'偏袒订单',d:'被故意推向某一个选择的订单。',alt:['偏袒单']},
  'mystery shopper':{w:'神秘顾客',d:'假装成普通顾客去买东西的测试员，这样商店或AI就不知道自己正在被检查。'},
  'twin':{w:'孪生AI',d:'审计时用的一个独立AI。它接到和被检查的AI一模一样的任务，好把两边的选择拿来比较。'},
  'independent':{w:'独立',d:'不归被检查的人管，也不拿他们的钱，所以可以有不同意见。'},
  'autopilot':{w:'全托管',d:'把一件事交给机器去管，自己不去检查。'},
  'bargain hunters':{w:'精打细算的顾客',d:'会仔细比较价格、想买到最划算东西的顾客。',alt:['精打细算']},
  'parent company':{w:'母公司',d:'拥有其他公司的公司。'},
